"""B22 Kai kit art generator (ImageGen via scripts/gen-image.py): writes prompts to art/kaikit/source and runs the audited Codex bridge for each missing sheet. Usage: python scripts/kaikit-art-gen.py [name ...]"""
import os, subprocess, sys
from concurrent.futures import ThreadPoolExecutor
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); OUT = os.path.join(ROOT, "art", "kaikit", "source"); os.makedirs(OUT, exist_ok=True)
FX = ("Original VFX sprite sheet for a chunky pixel-art 2D action game (KYNTRAZE: FRACTURE RUSH). Hand-painted pixel-art energy effects: hard crisp edges, bright saturated cores, dark-outlined shards, flat cel shading, NOT photographic, no soft blurry glow gradients, readable at 64-128 px. "
      "Isolated on a flat pure black (#000000) background with wide black gutters. A clean 2x2 grid of FOUR separate effects of equal size, each fully inside its own cell, nothing touching the cell edges. No text, no labels, no grid lines, no characters, no watermark. ")
IC = ("Original ability icon sheet for a 2D action game. Bold simple thick-stroke WHITE pictogram emblems (pure white #ffffff glyphs only, no colour, no shading, no outline halo) on a flat pure black (#000000) background, wide black gutters. A clean grid of SIX separate icons (3 columns by 2 rows) of equal size, each fully inside its cell, centred, readable at 48 px, consistent stroke weight and style. No text, no labels, no grid lines, no watermark. ")
J = {
 "fx_flare": FX + "Warm gold / orange palette. (1) A compact ki-blast sphere projectile pointing right: bright yellow-white core, orange fire shell, short flame tail. (2) A small explosion burst: orange-gold starburst with dark-outlined shards and ember dots. (3) A tall rising fire pillar seen side-on, erupting upward from the ground, narrow white-yellow core with gold-orange rim and flying embers, wider at the base. (4) A flat ground telegraph seen top-down at an angle: an ellipse ring of glowing orange runes with small ember points.",
 "fx_crucible": FX + "Warm gold / orange palette, solar theme. (1) A large flat ellipse sun-sigil ground circle seen at an angle: concentric gold rings, sun-ray glyph ticks, glowing orange inner disc. (2) A golden halo ring in three-quarter view with small flame points around it. (3) A final solar eruption: a column of gold-white fire bursting upward with a flat shockwave ring at its base and shards. (4) A comet impact: a bright gold-white star-shaped impact flash with dark-outlined shards and a flat shockwave ring.",
 "fx_silver": FX + "Cool silver / ice-lavender palette. (1) A teleport flash: concentric thin silver-lilac rings with glints and tiny diamond sparks. (2) A horizontal silver energy beam streak pointing right, white core, ice-blue rim, tapered ends. (3) A silver X-shaped strike slash flash with small diamond shards. (4) A small circular echo glyph: a silver-lavender rune circle with mirrored mini-runes, flat and clean.",
 "ic_kaikit": IC + "Icons left to right, top to bottom: (1) SURGE STEP: a boot with speed chevrons behind it and an upward arrow. (2) SCATTER BURST: a fist at the bottom with a fan of ten small round blasts radiating outward. (3) METEOR DRIVE: a fist driving forward trailing a comet tail with three impact ticks. (4) SILVER ECHO: two overlapping humanoid bust silhouettes, one solid and one drawn as an outline ghost. (5) RISING FLARE: an open palm facing forward with three rising flame columns in a row ahead of it. (6) SUNFALL CRUCIBLE: a sun disc with a descending ring beneath it and four inward-pointing arrows.",
}
def run(n):
    d = OUT; open(os.path.join(d, n + "-prompt.txt"), "w", encoding="utf8").write(J[n])
    if os.path.exists(os.path.join(d, n + ".png")): print("skip", n); return 0
    env = dict(os.environ); env.setdefault("CODEX_BIN", r"C:\Program Files\WindowsApps\OpenAI.Codex_26.1111.2228.0_x64__2p2nqsd0c76g0\app\resources\codex.exe")
    r = subprocess.run([sys.executable, os.path.join(ROOT, "scripts", "gen-image.py"), d, n], env=env, capture_output=True, text=True); print(n, r.returncode, (r.stdout + r.stderr)[-200:]); return r.returncode
names = sys.argv[1:] or list(J)
with ThreadPoolExecutor(4) as ex: list(ex.map(run, names))
